import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String inputStr = scanner.next();
        StringBuilder resultStr = new StringBuilder();
        boolean atFlag = false;
        inputStr += "###";

        for (int i = 0; i < inputStr.length() - 3; i++) {
            if (resultStr.length() == 0) {
                resultStr.append(inputStr.charAt(i));
                continue;
            }
            if (inputStr.charAt(i) == 'd' && inputStr.charAt(i + 1) == 'o' && inputStr.charAt(i + 2) == 't') {
                resultStr.append('.');
                i += 2;
            } else if (inputStr.charAt(i) == 'a' && inputStr.charAt(i + 1) == 't' && !atFlag) {
                atFlag = true;
                resultStr.append('@');
                i += 1;
            } else {
                resultStr.append(inputStr.charAt(i));
            }
        }

        if (resultStr.length() > 0 && resultStr.charAt(resultStr.length() - 1) == '.') {
            resultStr.setCharAt(resultStr.length() - 1, 'd');
            resultStr.append("ot");
        }

        System.out.println(resultStr.toString());
        scanner.close();
    }
}
